-- Codon — schema + seed (generated from the app's dataset)
-- Paste this whole file into Supabase → SQL Editor → Run.
-- jsonb-hybrid: queryable columns for search/filter + full object in "data".

create table if not exists institutions (
  id text primary key,
  slug text unique not null,
  name text,
  short text,
  data jsonb not null
);
create table if not exists sellers (
  id text primary key,
  slug text unique not null,
  name text,
  institution_id text,
  data jsonb not null
);
create table if not exists methods (
  id text primary key,
  slug text unique not null,
  title text,
  summary text,
  language text,
  fields text[],
  organisms text[],
  data_types text[],
  verification text,
  license_type text,
  pricing_model text,
  codon_id text,
  seller_id text,
  institution_id text,
  runs int,
  citations int,
  stars int,
  rating numeric,
  updated_at date,
  featured boolean,
  data jsonb not null
);

create index if not exists methods_fields_idx on methods using gin (fields);
create index if not exists methods_language_idx on methods (language);

-- public read (catalog is public); writes go through the secret key server-side
alter table institutions enable row level security;
alter table sellers enable row level security;
alter table methods enable row level security;
do $$ begin
  create policy "public read institutions" on institutions for select using (true);
exception when duplicate_object then null; end $$;
do $$ begin
  create policy "public read sellers" on sellers for select using (true);
exception when duplicate_object then null; end $$;
do $$ begin
  create policy "public read methods" on methods for select using (true);
exception when duplicate_object then null; end $$;

