insert into methods (id,slug,title,summary,language,fields,organisms,data_types,verification,license_type,pricing_model,codon_id,seller_id,institution_id,runs,citations,stars,rating,updated_at,featured,data) values ('m-cellineage','cellineage-vi','CellLineage-VI','Variational inference of single-cell differentiation trajectories and branch-point uncertainty from scRNA-seq.','Python',ARRAY['Single-cell']::text[],ARRAY['Mouse','Human']::text[],ARRAY['scRNA-seq','snRNA-seq']::text[],'verified','dual','dual','codon.2025.00417','seller-okafor','inst-lindgren',4127,38,412,4.8,'2025-05-18',true,'{"id":"m-cellineage","slug":"cellineage-vi","title":"CellLineage-VI","summary":"Variational inference of single-cell differentiation trajectories and branch-point uncertainty from scRNA-seq.","description":["CellLineage-VI fits a probabilistic latent-variable model to single-cell RNA-seq counts, jointly inferring a continuous developmental pseudotime, discrete lineage assignments, and calibrated uncertainty at branch points.","Unlike deterministic trajectory tools, the method propagates posterior uncertainty into every downstream estimate, so users can distinguish confident commitments from ambiguous transition states.","The packaged artifact reproduces the paper''s mouse hematopoiesis benchmark end-to-end, including the figure-3 branch-probability matrix, from a 2,000-cell sample."],"sellerId":"seller-okafor","institutionId":"inst-lindgren","fields":["Single-cell"],"organisms":["Mouse","Human"],"dataTypes":["scRNA-seq","snRNA-seq"],"language":"Python","status":"published","paperDoi":"10.1038/s41592-025-02218-3","paperTitle":"Calibrated variational inference of single-cell lineage trajectories","codonId":"codon.2025.00417","version":"1.3.0","versionHistory":[{"version":"1.3.0","date":"2025-05-18","note":"Reproduced on verifier v0.9.2","status":"verified"},{"version":"1.2.0","date":"2025-02-09","note":"Added GPU path; reproduced","status":"verified"},{"version":"1.0.0","date":"2024-11-01","note":"Initial verified release","status":"verified"}],"externalTools":[],"files":[{"name":"cellineage/","kind":"dir","children":[{"name":"model.py","kind":"file","fileType":"code","size":"18.4 KB"},{"name":"inference.py","kind":"file","fileType":"code","size":"22.1 KB"},{"name":"cli.py","kind":"file","fileType":"code","size":"6.7 KB"},{"name":"plotting.py","kind":"file","fileType":"code","size":"9.3 KB"}]},{"name":"environment.yml","kind":"file","fileType":"env","size":"1.1 KB"},{"name":"Dockerfile","kind":"file","fileType":"config","size":"812 B"},{"name":"data/","kind":"dir","children":[{"name":"sample_input.h5ad","kind":"file","fileType":"data","size":"14.2 MB"},{"name":"expected_branch_probs.csv","kind":"file","fileType":"data","size":"284 KB"}]},{"name":"README.md","kind":"file","fileType":"doc","size":"7.9 KB"},{"name":"codon.manifest.json","kind":"file","fileType":"config","size":"2.3 KB"}],"sampleInput":{"name":"sample_input.h5ad","format":"AnnData (HDF5)","preview":"AnnData object with n_obs × n_vars = 2000 × 2000\n  obs: ''cell_type'', ''batch'', ''phase''\n  var: ''gene_ids'', ''highly_variable''\n  layers: ''spliced'', ''unspliced''\n  uns: ''neighbors''"},"expectedOutput":{"name":"expected_branch_probs.csv","format":"CSV (2000 × 5)","preview":"cell_id,erythroid,myeloid,lymphoid,megakaryocyte,pseudotime\nAAAC-1,0.812,0.067,0.041,0.080,0.214\nAAAG-1,0.022,0.741,0.190,0.047,0.633\nAACT-1,0.105,0.118,0.690,0.087,0.588\n..."},"parameters":[{"name":"--n-latent","type":"int","default":"10","required":false,"description":"Dimensionality of the latent space."},{"name":"--n-lineages","type":"int","default":"auto","required":false,"description":"Number of terminal lineages; inferred if omitted."},{"name":"--seed","type":"int","default":"0","required":false,"description":"Random seed for deterministic inference."},{"name":"--max-epochs","type":"int","default":"400","required":false,"description":"Maximum training epochs."}],"license":{"type":"dual","spdx":"BSD-3-Clause / Commercial","name":"Academic-free, commercial license","terms":"Free for non-commercial academic research under BSD-3-Clause. Commercial use requires a paid license from the Okafor Lab via Lindgren Institute."},"pricing":{"model":"dual","currency":"USD","academicLabel":"Free for academic use","commercialAmount":2400,"runAmount":1.8,"unit":"commercial seat / yr"},"stats":{"runs":4127,"citations":38,"downloads":2210,"stars":412,"rating":4.8,"reviewCount":23},"reviews":[{"author":"Dr. Helen Zhou","affiliation":"Karzon Center for Developmental Biology","rating":5,"date":"2025-05-29","body":"Ran on our own bone-marrow dataset in one click. The calibrated branch probabilities matched our orthogonal lineage tracing remarkably well."},{"author":"Marcus Lindahl","affiliation":"Graduate student, Thorne University","rating":5,"date":"2025-04-12","body":"The fact that it reproduced the paper figure exactly before I touched it saved me a week of dependency wrangling."}],"readme":"# CellLineage-VI\n\nCalibrated variational inference of single-cell lineage trajectories.\n\n## Quickstart\n\n```bash\ncellineage fit data/sample_input.h5ad --n-lineages auto --seed 0 \\\n  --out results/branch_probs.csv\n```\n\nThe verified run reproduces `data/expected_branch_probs.csv` within a 1e-4\nnumerical tolerance on the posterior branch-probability matrix.\n\n## Inputs\n\n- An `AnnData` `.h5ad` file with spliced/unspliced layers.\n\n## Outputs\n\n- A per-cell branch-probability matrix and continuous pseudotime.","createdAt":"2024-11-01","updatedAt":"2025-05-18","featured":true,"verification":{"id":"ver-cellineage-130","status":"verified","startedAt":"2025-05-18T14:02:11Z","finishedAt":"2025-05-18T14:09:54Z","durationSec":463,"verifierVersion":"codon-verifier 0.9.2","baseImage":"python:3.11-slim","imageDigest":"sha256:00000008ceff139953d8451100080a8423fac78dee34d8d60000000875fc9ceb","inputHash":"blake3:0c00001e4ad2be559b1b8c82000002ce4a56d0291143b1d0000000084ad252dd","expectedOutputHash":"blake3:0000000008062ef9ad115deb000000842d8516c889b485480000001084ec49a4","actualOutputHash":"blake3:0000000008062ef9ad115deb000000842d8516c889b485480000001084ec49a4","toleranceProfile":"numeric: atol 1e-4, rtol 1e-3 (float matrices)","runExitCode":0,"runWallSec":271,"peakMemoryMb":3820,"buildSteps":[{"label":"Resolve conda environment (lock)","status":"ok","durationSec":96},{"label":"Build OCI image","status":"ok","durationSec":88},{"label":"Pin dependency graph (142 packages)","status":"ok","durationSec":8},{"label":"Sandbox run on sample input","status":"ok","durationSec":271}],"resourceLimits":{"cpu":"4 vCPU","memory":"8 GB","timeout":"30 min","egress":"none (network disabled)","outputCap":"512 MB"},"diff":[{"name":"branch_probs.csv","kind":"numeric","status":"match","detail":"2000×5 float matrix within atol 1e-4 (max abs Δ = 3.1e-5).","tolerance":"atol 1e-4 / rtol 1e-3"},{"name":"pseudotime column","kind":"numeric","status":"match","detail":"Spearman ρ = 1.000 vs expected ordering.","tolerance":"atol 1e-4"}]}}'::jsonb) on conflict (id) do update set data=excluded.data;
insert into methods (id,slug,title,summary,language,fields,organisms,data_types,verification,license_type,pricing_model,codon_id,seller_id,institution_id,runs,citations,stars,rating,updated_at,featured,data) values ('m-varsig','varsig-somatic','VarSig','Reproducible somatic variant interpretation pipeline scoring pathogenicity and actionability from tumor WES/WGS.','Nextflow',ARRAY['Genomics / variants']::text[],ARRAY['Human']::text[],ARRAY['WGS','WES']::text[],'verified','dual','dual','codon.2025.00622','seller-reyes','inst-meridian',9320,51,688,4.7,'2025-06-01',true,'{"id":"m-varsig","slug":"varsig-somatic","title":"VarSig","summary":"Reproducible somatic variant interpretation pipeline scoring pathogenicity and actionability from tumor WES/WGS.","description":["VarSig is an end-to-end Nextflow pipeline that annotates somatic variants, integrates population and functional evidence, and produces a ranked, clinically structured pathogenicity report.","It bundles a pinned reference snapshot manifest so results are stable across runs, and emits a deterministic JSON report alongside a human-readable summary.","The verified artifact reproduces the cohort benchmark report for a 50-variant sample VCF."],"sellerId":"seller-reyes","institutionId":"inst-meridian","fields":["Genomics / variants"],"organisms":["Human"],"dataTypes":["WGS","WES"],"language":"Nextflow","status":"published","paperDoi":"10.1186/s13073-025-01411-7","paperTitle":"VarSig: transparent somatic variant interpretation at cohort scale","codonId":"codon.2025.00622","version":"2.1.4","versionHistory":[{"version":"2.1.4","date":"2025-06-01","note":"Reference snapshot refresh; reproduced","status":"verified"},{"version":"2.0.0","date":"2025-03-15","note":"Nextflow DSL2 rewrite","status":"verified"}],"externalTools":[],"files":[{"name":"main.nf","kind":"file","fileType":"code","size":"12.0 KB"},{"name":"nextflow.config","kind":"file","fileType":"config","size":"3.4 KB"},{"name":"modules/","kind":"dir","children":[{"name":"annotate.nf","kind":"file","fileType":"code","size":"5.1 KB"},{"name":"score.nf","kind":"file","fileType":"code","size":"7.8 KB"},{"name":"report.nf","kind":"file","fileType":"code","size":"4.2 KB"}]},{"name":"env/Dockerfile","kind":"file","fileType":"config","size":"1.4 KB"},{"name":"test/","kind":"dir","children":[{"name":"sample.vcf.gz","kind":"file","fileType":"data","size":"82 KB"},{"name":"expected_report.json","kind":"file","fileType":"data","size":"47 KB"}]},{"name":"README.md","kind":"file","fileType":"doc","size":"11.2 KB"}],"sampleInput":{"name":"sample.vcf.gz","format":"VCF 4.2 (bgzipped)","preview":"##fileformat=VCFv4.2\n#CHROM POS ID REF ALT QUAL FILTER INFO\nchr7 140453136 . A T 312 PASS DP=210;AF=0.31\nchr17 7674220 . C T 287 PASS DP=180;AF=0.44\nchr12 25245350 . C A 301 PASS DP=199;AF=0.28"},"expectedOutput":{"name":"expected_report.json","format":"JSON","preview":"{\n  \"variants\": [\n    {\"gene\": \"BRAF\", \"hgvs\": \"p.V600E\", \"tier\": \"I\",\n     \"pathogenicity\": 0.98, \"actionable\": true},\n    {\"gene\": \"TP53\", \"hgvs\": \"p.R175H\", \"tier\": \"I\",\n     \"pathogenicity\": 0.95, \"actionable\": false}\n  ],\n  \"summary\": {\"tier_I\": 2, \"tier_II\": 5, \"vus\": 18}\n}"},"parameters":[{"name":"--input","type":"path","default":"—","required":true,"description":"Input somatic VCF (bgzipped)."},{"name":"--assembly","type":"enum","default":"GRCh38","required":false,"description":"Reference assembly (GRCh37 | GRCh38)."},{"name":"--min-af","type":"float","default":"0.05","required":false,"description":"Minimum variant allele fraction."}],"license":{"type":"dual","spdx":"Apache-2.0 / Commercial","name":"Academic-free, commercial license","terms":"Apache-2.0 for academic and non-commercial use. Commercial / clinical deployment requires a Meridian Therapeutics commercial license."},"pricing":{"model":"dual","currency":"USD","academicLabel":"Free for academic use","commercialAmount":9000,"runAmount":0.9,"unit":"commercial site / yr"},"stats":{"runs":9320,"citations":51,"downloads":3870,"stars":688,"rating":4.7,"reviewCount":31},"reviews":[{"author":"Dr. Anika Brandt","affiliation":"Molecular Tumor Board, St. Eldon Hospital","rating":5,"date":"2025-06-10","body":"Deterministic reports we can actually defend in a tumor board. The pinned reference snapshot is the detail everyone else skips."}],"readme":"# VarSig\n\nTransparent somatic variant interpretation.\n\n```bash\nnextflow run main.nf --input test/sample.vcf.gz --assembly GRCh38\n```\n\nReproduces `test/expected_report.json` exactly (structural JSON match).","createdAt":"2025-03-15","updatedAt":"2025-06-01","featured":true,"verification":{"id":"ver-varsig-214","status":"verified","startedAt":"2025-06-01T09:31:00Z","finishedAt":"2025-06-01T09:44:22Z","durationSec":802,"verifierVersion":"codon-verifier 0.9.2","baseImage":"nextflow/nextflow:24.10.0","imageDigest":"sha256:00000008c46530e71b07813600004000ced25ca9fb604d84000002c8c61d4371","inputHash":"blake3:00000000816d723096f374b50000001000cc1009857d6fd000000008c631c05b","expectedOutputHash":"blake3:000000084214833f136e379a00000008cefb210f3ccd8db700000208cef7358f","actualOutputHash":"blake3:000000084214833f136e379a00000008cefb210f3ccd8db700000208cef7358f","toleranceProfile":"structural: JSON key/value exact match; floats atol 1e-6","runExitCode":0,"runWallSec":524,"peakMemoryMb":5120,"buildSteps":[{"label":"Resolve container images (3 processes)","status":"ok","durationSec":142},{"label":"Pin reference snapshot manifest","status":"ok","durationSec":36},{"label":"Build OCI image","status":"ok","durationSec":100},{"label":"Sandbox pipeline run","status":"ok","durationSec":524}],"resourceLimits":{"cpu":"8 vCPU","memory":"16 GB","timeout":"45 min","egress":"none (network disabled)","outputCap":"1 GB"},"diff":[{"name":"report.json","kind":"structural","status":"match","detail":"All 25 variant records and summary counts match expected keys/values.","tolerance":"exact (structural)"},{"name":"pathogenicity scores","kind":"numeric","status":"match","detail":"Per-variant scores within atol 1e-6.","tolerance":"atol 1e-6"}]}}'::jsonb) on conflict (id) do update set data=excluded.data;
insert into methods (id,slug,title,summary,language,fields,organisms,data_types,verification,license_type,pricing_model,codon_id,seller_id,institution_id,runs,citations,stars,rating,updated_at,featured,data) values ('m-dockstream','dockstream-ad','DockStream-AD','Ensemble molecular docking protocol with consensus rescoring for small-molecule virtual screening.','Python',ARRAY['Structural biology']::text[],ARRAY['Human']::text[],ARRAY['PDB / structures']::text[],'external-dep','open','free','codon.2025.00731','seller-salomon','inst-baysb',2740,19,233,4.5,'2025-05-30',false,'{"id":"m-dockstream","slug":"dockstream-ad","title":"DockStream-AD","summary":"Ensemble molecular docking protocol with consensus rescoring for small-molecule virtual screening.","description":["DockStream-AD orchestrates ensemble docking across multiple receptor conformations and applies a consensus rescoring function to rank candidate ligands.","Because docking depends on the proprietary AutoDock Vina binary, the method is verified in declared-external-tool mode: Codon confirms the pipeline, scoring, and output schema reproduce on a provisioned licensed runner, and the listing flags the external requirement.","The sample screens 12 ligands against a kinase ensemble and reproduces the ranked affinity table."],"sellerId":"seller-salomon","institutionId":"inst-baysb","fields":["Structural biology"],"organisms":["Human"],"dataTypes":["PDB / structures"],"language":"Python","status":"published","paperDoi":"10.1021/acs.jcim.5c00219","paperTitle":"Consensus ensemble docking for robust virtual screening","codonId":"codon.2025.00731","version":"1.0.2","versionHistory":[{"version":"1.0.2","date":"2025-05-30","note":"Verified with external dependency (AutoDock Vina)","status":"external-dep"}],"externalTools":[{"name":"AutoDock Vina","version":"1.2.5","kind":"proprietary","licenseNote":"Apache-2.0 binary; provisioned on Codon licensed runner."},{"name":"Open Babel","version":"3.1.1","kind":"open","licenseNo