ingle-receptor docking. Nice that Codon handled the Vina licensing on the run node."}],"readme":"# DockStream-AD\n\nEnsemble docking with consensus rescoring.\n\n> Requires AutoDock Vina (provisioned on Codon licensed runners).\n\n```bash\npython -m dockstream.ensemble --receptors receptors/ensemble.pdbqt \\\n  --ligands test/ligands.smi --seed 42\n```","createdAt":"2025-05-30","updatedAt":"2025-05-30","featured":false,"verification":{"id":"ver-dockstream-102","status":"external-dep","startedAt":"2025-05-30T18:10:00Z","finishedAt":"2025-05-30T18:27:40Z","durationSec":1060,"verifierVersion":"codon-verifier 0.9.2","baseImage":"ubuntu:22.04 + Vina 1.2.5 (licensed runner)","imageDigest":"sha256:0000010000403dda41916fb60000001084e1b6976e9b5c0700080008c6bda30d","inputHash":"blake3:0000008cebb8ff090c91e0c50c0000842a0e60c67e1acfdb00000008cef7358f","expectedOutputHash":"blake3:00000000846df65591ce0537000000084206b1ee0a745e4b00088084237e602a","actualOutputHash":"blake3:00000000846df65591ce0537000000084206b1ee0a745e4b00088084237e602a","toleranceProfile":"numeric: scores atol 0.05 kcal/mol; ranking exact","runExitCode":0,"runWallSec":879,"peakMemoryMb":2240,"buildSteps":[{"label":"Build base image + Open Babel","status":"ok","durationSec":121},{"label":"Attach licensed AutoDock Vina runner","status":"ok","durationSec":44},{"label":"Pin dependency graph (38 packages)","status":"ok","durationSec":16},{"label":"Sandbox docking run (12 ligands)","status":"ok","durationSec":879}],"resourceLimits":{"cpu":"8 vCPU","memory":"8 GB","timeout":"60 min","egress":"none (network disabled)","outputCap":"512 MB"},"diff":[{"name":"ranking order","kind":"exact","status":"match","detail":"Top-12 ranking identical to expected.","tolerance":"exact"},{"name":"consensus_score","kind":"numeric","status":"match","detail":"Within atol 0.05 kcal/mol (max Δ = 0.03).","tolerance":"atol 0.05"}],"notes":"Verified with external dependency: AutoDock Vina is proprietary-adjacent and provisioned on an isolated licensed runner. The badge reflects reproducibility under that declared dependency."}}'::jsonb) on conflict (id) do update set data=excluded.data;
insert into methods (id,slug,title,summary,language,fields,organisms,data_types,verification,license_type,pricing_model,codon_id,seller_id,institution_id,runs,citations,stars,rating,updated_at,featured,data) values ('m-neuroseg','neuroseg3d','NeuroSeg3D','Deep-learning segmentation of chronic stroke lesions from 3D T1/FLAIR brain MRI with volumetric reporting.','Python',ARRAY['Neuroimaging']::text[],ARRAY['Human']::text[],ARRAY['MRI']::text[],'verified','commercial','paid','codon.2025.00588','seller-vasquez','inst-northcrest',1880,14,176,4.6,'2025-05-22',true,'{"id":"m-neuroseg","slug":"neuroseg3d","title":"NeuroSeg3D","summary":"Deep-learning segmentation of chronic stroke lesions from 3D T1/FLAIR brain MRI with volumetric reporting.","description":["NeuroSeg3D is a 3D U-Net pipeline that segments chronic stroke lesions from co-registered T1 and FLAIR volumes and outputs lesion masks plus a volumetric report.","The artifact ships pinned model weights and reproduces the held-out test subject''s Dice score and lesion volume from a single anonymized scan pair.","Inference runs on CPU in the sandbox; a GPU path is available for the Run service."],"sellerId":"seller-vasquez","institutionId":"inst-northcrest","fields":["Neuroimaging"],"organisms":["Human"],"dataTypes":["MRI"],"language":"Python","status":"published","paperDoi":"10.1016/j.media.2025.103217","paperTitle":"Robust 3D segmentation of chronic stroke lesions across scanners","codonId":"codon.2025.00588","version":"1.1.0","versionHistory":[{"version":"1.1.0","date":"2025-05-22","note":"Cross-scanner weights; reproduced","status":"verified"},{"version":"1.0.0","date":"2025-03-30","note":"Initial verified release","status":"verified"}],"externalTools":[],"files":[{"name":"neuroseg/","kind":"dir","children":[{"name":"model.py","kind":"file","fileType":"code","size":"16.7 KB"},{"name":"infer.py","kind":"file","fileType":"code","size":"7.4 KB"},{"name":"report.py","kind":"file","fileType":"code","size":"5.1 KB"}]},{"name":"weights/unet3d.pt","kind":"file","fileType":"data","size":"58 MB"},{"name":"requirements.txt","kind":"file","fileType":"env","size":"720 B"},{"name":"Dockerfile","kind":"file","fileType":"config","size":"1.2 KB"},{"name":"test/sub-001_T1.nii.gz","kind":"file","fileType":"data","size":"6.4 MB"},{"name":"test/expected_mask.nii.gz","kind":"file","fileType":"data","size":"211 KB"},{"name":"README.md","kind":"file","fileType":"doc","size":"9.5 KB"}],"sampleInput":{"name":"sub-001_T1.nii.gz","format":"NIfTI (3D, 1mm iso)","preview":"NIfTI-1 volume\n  dim:      [3, 182, 218, 182]\n  pixdim:   [1.0, 1.0, 1.0] mm\n  datatype: FLOAT32\n  paired:   sub-001_FLAIR.nii.gz"},"expectedOutput":{"name":"expected_mask.nii.gz","format":"NIfTI (binary mask) + JSON","preview":"{\n  \"lesion_volume_ml\": 23.7,\n  \"dice_vs_reference\": 0.871,\n  \"n_components\": 2,\n  \"hemisphere\": \"left\"\n}"},"parameters":[{"name":"--t1","type":"path","default":"—","required":true,"description":"T1-weighted NIfTI volume."},{"name":"--flair","type":"path","default":"—","required":true,"description":"Co-registered FLAIR NIfTI volume."},{"name":"--threshold","type":"float","default":"0.5","required":false,"description":"Probability threshold for the mask."}],"license":{"type":"commercial","spdx":"Proprietary","name":"Direct paid license","terms":"Proprietary research license sold by Northcrest UMC. Includes model weights and a non-redistribution clause."},"pricing":{"model":"paid","currency":"USD","amount":1500,"runAmount":2.5,"unit":"research license"},"stats":{"runs":1880,"citations":14,"downloads":540,"stars":176,"rating":4.6,"reviewCount":9},"reviews":[{"author":"Dr. Sofia Marchetti","affiliation":"Stroke Imaging Unit, Riveredge Hospital","rating":5,"date":"2025-05-27","body":"Reproduced the published Dice on our scanner without retraining. The volumetric report drops straight into our workflow."}],"readme":"# NeuroSeg3D\n\n3D stroke lesion segmentation.\n\n```bash\npython -m neuroseg.infer --t1 test/sub-001_T1.nii.gz \\\n  --flair test/sub-001_FLAIR.nii.gz --out results/\n```\n\nReproduces lesion volume (ml) and Dice within tolerance.","createdAt":"2025-03-30","updatedAt":"2025-05-22","featured":true,"verification":{"id":"ver-neuroseg-110","status":"verified","startedAt":"2025-05-22T11:00:00Z","finishedAt":"2025-05-22T11:06:18Z","durationSec":378,"verifierVersion":"codon-verifier 0.9.2","baseImage":"python:3.10-slim","imageDigest":"sha256:00000018421ccdc19d62acd8000000008caf4ec843acc4600000001847cdf655","inputHash":"blake3:000002ebcefffb70cfb9d0660000400008858d8f3c7dabd500000008cef488c7","expectedOutputHash":"blake3:00000000080eeca1be945191000000176793f724348dc10000000008ce739cc1","actualOutputHash":"blake3:00000000080eeca1be945191000000176793f724348dc10000000008ce739cc1","toleranceProfile":"numeric: lesion volume atol 0.1 ml; Dice atol 1e-3; mask checksum","runExitCode":0,"runWallSec":198,"peakMemoryMb":6400,"buildSteps":[{"label":"Resolve pip requirements (pinned)","status":"ok","durationSec":71},{"label":"Build OCI image + load weights","status":"ok","durationSec":92},{"label":"Pin dependency graph (61 packages)","status":"ok","durationSec":9},{"label":"Sandbox CPU inference","status":"ok","durationSec":198}],"resourceLimits":{"cpu":"8 vCPU","memory":"16 GB","timeout":"30 min","egress":"none (network disabled)","outputCap":"512 MB"},"diff":[{"name":"lesion_volume_ml","kind":"numeric","status":"match","detail":"23.7 ml vs 23.7 ml (Δ = 0.02).","tolerance":"atol 0.1 ml"},{"name":"dice_vs_reference","kind":"numeric","status":"match","detail":"0.871 vs 0.871 (Δ = 4e-4).","tolerance":"atol 1e-3"},{"name":"mask.nii.gz","kind":"checksum","status":"match","detail":"Binary mask checksum identical after canonicalization.","tolerance":"checksum"}]}}'::jsonb) on conflict (id) do update set data=excluded.data;
