4808cefffb78","toleranceProfile":"numeric: proportions atol 1e-3 (rows sum to 1)","runExitCode":0,"runWallSec":188,"peakMemoryMb":4100,"buildSteps":[{"label":"Restore renv lockfile (203 packages)","status":"ok","durationSec":121},{"label":"Build OCI image","status":"ok","durationSec":26},{"label":"Sandbox run on Visium sample","status":"ok","durationSec":188}],"resourceLimits":{"cpu":"4 vCPU","memory":"8 GB","timeout":"30 min","egress":"none (network disabled)","outputCap":"256 MB"},"diff":[{"name":"proportions.csv","kind":"numeric","status":"match","detail":"500×7 matrix within atol 1e-3; rows sum to 1.000.","tolerance":"atol 1e-3"}]}}'::jsonb) on conflict (id) do update set data=excluded.data;
insert into methods (id,slug,title,summary,language,fields,organisms,data_types,verification,license_type,pricing_model,codon_id,seller_id,institution_id,runs,citations,stars,rating,updated_at,featured,data) values ('m-protmpnn','protmpnn-tune','ProtMPNN-Tune','Fine-tuning toolkit for inverse-folding protein sequence design with fixed-backbone constraints.','Python',ARRAY['Protein design']::text[],ARRAY['Pan-species']::text[],ARRAY['PDB / structures']::text[],'verified','open','free','codon.2025.00640','seller-nair','inst-thorne',5210,27,901,4.9,'2025-05-09',false,'{"id":"m-protmpnn","slug":"protmpnn-tune","title":"ProtMPNN-Tune","summary":"Fine-tuning toolkit for inverse-folding protein sequence design with fixed-backbone constraints.","description":["ProtMPNN-Tune fine-tunes a message-passing inverse-folding model to design sequences for a target backbone under user-specified position constraints.","The verified sample designs sequences for a small fixed backbone and reproduces the recovery-rate metric and the top sequence."],"sellerId":"seller-nair","institutionId":"inst-thorne","fields":["Protein design"],"organisms":["Pan-species"],"dataTypes":["PDB / structures"],"language":"Python","status":"published","paperDoi":"10.1126/science.adp9921","paperTitle":"Constraint-aware fine-tuning for inverse protein folding","codonId":"codon.2025.00640","version":"0.4.0","versionHistory":[{"version":"0.4.0","date":"2025-05-09","note":"Constraint API; reproduced","status":"verified"}],"externalTools":[{"name":"CUDA Runtime","version":"12.4","kind":"gpu","licenseNote":"Optional GPU acceleration on the Run service."}],"files":[{"name":"protmpnn_tune/","kind":"dir","children":[{"name":"design.py","kind":"file","fileType":"code","size":"12.1 KB"},{"name":"constraints.py","kind":"file","fileType":"code","size":"5.4 KB"}]},{"name":"pyproject.toml","kind":"file","fileType":"env","size":"1.3 KB"},{"name":"Dockerfile","kind":"file","fileType":"config","size":"980 B"},{"name":"test/backbone.pdb","kind":"file","fileType":"data","size":"88 KB"},{"name":"test/expected_design.json","kind":"file","fileType":"data","size":"4 KB"},{"name":"README.md","kind":"file","fileType":"doc","size":"5.0 KB"}],"sampleInput":{"name":"backbone.pdb","format":"PDB (fixed backbone)","preview":"HEADER    DE NOVO BACKBONE\nATOM      1  N   GLY A   1      11.104  6.134  ...\nATOM      2  CA  GLY A   1      12.560  6.057  ...\n... (64 residues)"},"expectedOutput":{"name":"expected_design.json","format":"JSON","preview":"{\n  \"top_sequence\": \"MKTAYIAKQR...\",\n  \"recovery_rate\": 0.486,\n  \"n_designs\": 8,\n  \"mean_score\": -1.27\n}"},"parameters":[{"name":"--backbone","type":"path","default":"—","required":true,"description":"Fixed-backbone PDB."},{"name":"--fix","type":"list","default":"[]","required":false,"description":"Positions to hold fixed."},{"name":"--temperature","type":"float","default":"0.1","required":false,"description":"Sampling temperature."},{"name":"--seed","type":"int","default":"0","required":false,"description":"Random seed."}],"license":{"type":"open","spdx":"MIT","name":"MIT (open source)","terms":"MIT licensed. Free for any use including commercial."},"pricing":{"model":"free","currency":"USD","runAmount":4},"stats":{"runs":5210,"citations":27,"downloads":4120,"stars":901,"rating":4.9,"reviewCount":19},"reviews":[{"author":"Dr. Elias Norén","affiliation":"Protein Engineering, Vantage Bio","rating":5,"date":"2025-05-20","body":"Cleanest inverse-folding fine-tuning code I''ve used. Reproduced the recovery rate to the third decimal on first run."}],"readme":"# ProtMPNN-Tune\n\nConstraint-aware inverse folding.\n\n```bash\nprotmpnn-tune design --backbone test/backbone.pdb --temperature 0.1 --seed 0\n```","createdAt":"2025-05-09","updatedAt":"2025-05-09","featured":false,"verification":{"id":"ver-protmpnn-040","status":"verified","startedAt":"2025-05-09T13:00:00Z","finishedAt":"2025-05-09T13:05:02Z","durationSec":302,"verifierVersion":"codon-verifie